const CLERIC_DOMAIN_SPELL_SLOT_COUNT_AT_LEVEL_11: i16 = 6;
const CLERIC_DOMAIN_SPELL_SLOT_COUNT_AT_LEVEL_13: i16 = 7;
const CLERIC_DOMAIN_SPELL_SLOT_COUNT_AT_LEVEL_15: i16 = 8;
